def redact_headers(headers: dict[str, str]) -> dict[str, str]:
    out = dict(headers)
    if "Authorization" in out:
        scheme = out["Authorization"].split(" ", 1)[0]
        out["Authorization"] = f"{scheme} ***"
    return out


40→def format_request(method: str, url: str, headers: dict[str, str], body: Any) -> str:
    lines = [f">>> {method} {url}", ">>> headers:"]
    lines.append(json.dumps(redact_headers(headers), indent=2, ensure_ascii=False))
    if body is not None:
        lines.append(">>> body:")
        lines.append(json.dumps(body, indent=2, ensure_ascii=False))
    return "\n".join(lines)


def _strip_ns(tag: str) -> str:
50→    return tag.rsplit("}", 1)[-1]


def _element_to_value(el: ElementTree.Element) -> Any:
    children = list(el)
    if not children:
        return (el.text or "").strip()
    result: dict[str, Any] = {}
    for child in children:
        tag = _strip_ns(child.tag)
60→        value = _element_to_value(child)
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[tag] = [existing, value]
        else:
            result[tag] = value
    return result
